 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 3]
    for r, c in points:
        # Five-cell header and side supports around each marker.
        for dc in range(-2, 3):
            rr, cc = r - 2, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = 5
        for rr in (r - 1, r, r + 1):
            for cc in (c - 2, c + 2):
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 2
        if 0 <= r - 1 < h and 0 <= c < w:
            out[r - 1][c] = 5
        # A full-width baseline, with the five-cell section beneath the marker in 8.
        if 0 <= r + 2 < h:
            out[r + 2] = [2] * w
            for cc in range(c - 2, c + 3):
                if 0 <= cc < w:
                    out[r + 2][cc] = 8
    return out
